var scene=UnityEditor.SceneManagement.EditorSceneManager.NewPreviewScene();var go=(GameObject)UnityEditor.PrefabUtility.InstantiatePrefab(UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ChibiSurvivor/Bandit/SimpleBandit/SimpleBandit.prefab"),scene);
try{go.GetComponentInChildren<Animator>().enabled=false;var bones=go.GetComponentsInChildren<Transform>();var source=UnityEditor.AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/ChibiSurvivor/Player/SimpleHeroStudy/Game/BatWalk.anim");var rows=new System.Collections.Generic.List<object>();
for(int i=0;i<12;i++){source.SampleAnimation(go,i*source.length/12);rows.Add(new{phase=i/12f,bones=bones.Where(t=>new[]{"Hips","Chest","Thigh.L","Shin.L","Foot.L","Foot.R"}.Contains(t.name)).Select(t=>new{t.name,p=t.position.ToString("F3"),q=t.rotation.eulerAngles.ToString("F1")}).ToArray()});}return rows;}finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(scene);}
